const t = $('On Telegram Message1').first().json;
const m = t.message || {};
const transcript = ($input.first().json.text || $input.first().json.transcription || '').toString().trim();
return [{ json: {
  text: transcript,
  caption: '',
  documentMime: '',
  chat: m.chat || {}
} }];

const cls = ($input.first().json.text || $input.first().json.response || '').toString().toLowerCase().trim();
let intent = 'invalid';
if (cls.indexOf('submission') !== -1) intent = 'submission';
else if (cls.indexOf('problem') !== -1) intent = 'problem';
else if (cls.indexOf('question') !== -1) intent = 'question';
function safe(n){ try { return $(n).first().json; } catch (e) { return null; } }
const norm = safe('Build Normalized Text') || safe('Build Voice Message') || {};
const trigMsg = ($('On Telegram Message1').first().json.message) || {};
return [{ json: {
  intent: intent,
  text: (norm.text || '').toString(),
  caption: (norm.caption || '').toString(),
  documentMime: (norm.documentMime || '').toString(),
  message: trigMsg,
  chat: trigMsg.chat || norm.chat || {}
} }];

const p = $input.first().json || {};
const prof = $('Get Profile').first().json || {};
const pi = $('Prepare Intent').first().json || {};
let lines = [];
lines.push('STUDENT PROFILE');
lines.push('Name: ' + (p.full_name || prof.full_name || ''));
lines.push('Student Code: ' + (p.student_code || prof.student_code || ''));
lines.push('Department: ' + (p.department || prof.department || ''));
lines.push('Academic Year: ' + (p.academic_year || prof.academic_year || ''));
lines.push('');
lines.push('REGISTERED COURSES:');
(p.enrollments || []).forEach(function(e){ const c = e.courses || {}; lines.push('- ' + (c.course_name || '') + ' (' + (c.course_code || '') + ') ' + (c.semester || '')); });
lines.push('');
lines.push('GRADES:');
(p.grades || []).forEach(function(g){ const a = g.assignments || {}; lines.push('- ' + (a.title || '') + ': final ' + (g.final_grade != null ? g.final_grade : 'N/A') + ', ai ' + (g.ai_grade != null ? g.ai_grade : 'N/A') + ', status ' + (g.status || '') + ' (max ' + (a.max_grade != null ? a.max_grade : '') + ')'); });
return [{ json: {
  knowledge: lines.join(String.fromCharCode(10)),
  role: 'student',
  subjectId: (prof.student_code || prof.id || '').toString(),
  subjectName: (prof.full_name || '').toString(),
  question: (pi.text || '').toString()
} }];

const p = $input.first().json || {};
const prof = $('Get Profile').first().json || {};
const pi = $('Prepare Intent').first().json || {};
let lines = [];
lines.push('PROFESSOR PROFILE');
lines.push('Name: ' + (p.full_name || prof.full_name || ''));
lines.push('');
lines.push('COURSES TAUGHT:');
(p.courses || []).forEach(function(c){
  lines.push('Course: ' + (c.course_name || '') + ' (' + (c.course_code || '') + ')');
  (c.assignments || []).forEach(function(a){
    lines.push('  Assignment: ' + (a.title || ''));
    (a.grades || []).forEach(function(g){ lines.push('    Student ' + (g.student_id || '') + ': ' + (g.final_grade != null ? g.final_grade : 'N/A')); });
  });
});
return [{ json: {
  knowledge: lines.join(String.fromCharCode(10)),
  role: 'professor',
  subjectId: (prof.id || '').toString(),
  subjectName: (prof.full_name || '').toString(),
  question: (pi.text || '').toString()
} }];

const msg = ($input.first().json.message) || {};
const caption = (msg.caption || '').trim();
const lines = caption.split('\n').map(function (l) { return l.trim(); }).filter(Boolean);
const idMatch = caption.match(/\b\d{6,10}\b/);
const studentName = lines[0] || '';
const assignmentLine = lines.filter(function (l) { return /assignment/i.test(l); })[0];
const doc = msg.document || {};
return [{ json: {
  studentName: studentName,
  studentNameSlug: (studentName.replace(/\s+/g, '_') || 'Student'),
  studentId: idMatch ? idMatch[0] : '',
  assignment: assignmentLine || 'Assignment 1',
  assignmentSlug: (assignmentLine || 'Assignment 1').replace(/\s+/g, ''),
  chatId: (msg.chat || {}).id,
  username: (msg.chat || {}).username || '',
  fileId: doc.file_id || '',
  originalFileName: doc.file_name || ''
} }];

let raw = ($input.first().json.text || $input.first().json.response || '').toString();
raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
let data;
try {
  data = JSON.parse(raw);
} catch (e) {
  throw new Error('Gemini returned non-JSON output: ' + raw.slice(0, 300));
}
function join(v) { return Array.isArray(v) ? v.join('; ') : (v || ''); }
const score = (data.score === undefined || data.score === null) ? '' : data.score;
return [{ json: {
  score: score,
  content: data.content, grammar: data.grammar, research: data.research,
  references: data.references, formatting: data.formatting,
  criticalThinking: data.criticalThinking, originality: data.originality,
  strengths: join(data.strengths),
  weaknesses: join(data.weaknesses),
  suggestions: join(data.suggestions),
  feedback: data.feedback || '',
  status: (score !== '' ? 'Graded' : 'Pending Review')
} }];

const d = ($input.first().json.data) || {};
const ai = $('Parse Score & Feedback1').item.json;
function pick(o, keys){ for (var i=0;i<keys.length;i++){ var k=keys[i]; if (o[k]!==undefined && o[k]!=='') return o[k]; } return ''; }
const decision = (pick(d,['Decision','decision','text','Approval'])||'Approve').toString();
const dl = decision.toLowerCase();
const profRaw = pick(d,['Professor Score','professorScore','Score']);
const profScore = (profRaw==='' ? '' : Number(profRaw));
let finalScore = ai.score;
let approvalStatus = 'Approved';
if (dl.indexOf('reject')!==-1 || dl.indexOf('declin')!==-1) { approvalStatus='Rejected'; finalScore=''; }
else if (dl.indexOf('modif')!==-1 && profScore!=='') { approvalStatus='Modified'; finalScore=profScore; }
else if (profScore!=='' && profScore!==ai.score) { approvalStatus='Modified'; finalScore=profScore; }
const aiFeedback = [
  ai.feedback ? ('Feedback: ' + ai.feedback) : '',
  ai.strengths ? ('Strengths: ' + ai.strengths) : '',
  ai.weaknesses ? ('Weaknesses: ' + ai.weaknesses) : '',
  ai.suggestions ? ('Suggestions: ' + ai.suggestions) : ''
].filter(Boolean).join(String.fromCharCode(10));
return [{ json: Object.assign({}, ai, {
  aiScore: ai.score,
  professorScore: profScore,
  finalScore: finalScore,
  ai_feedback: aiFeedback,
  approvalStatus: approvalStatus,
  approvalTime: new Date().toISOString()
}) }];

const t = $('On Telegram Message1').first().json;
const m = t.message || {};
return [{ json: {
  text: (m.text || '').toString(),
  caption: (m.caption || '').toString(),
  documentMime: ((m.document || {}).mime_type || '').toString(),
  chat: m.chat || {}
} }];
